package main

import (
    "bytes"
    "crypto/sha256"
    "encoding/hex"
    "encoding/json"
    "errors"
    "flag"
    "fmt"
    "io"
    "os"
    "unicode/utf8"

    "practice"
)

func run(args []string) error {
    flags := flag.NewFlagSet("exporter", flag.ContinueOnError)
    flags.SetOutput(io.Discard)
    input := flags.String("input", "", "JSON records file")
    output := flags.String("output", "", "export destination")
    if err := flags.Parse(args); err != nil { return err }
    if *input == "" || *output == "" || flags.NArg() != 0 {
        return errors.New("--input and --output are required; no positional arguments")
    }
    inputInfo, err := os.Stat(*input)
    if err != nil { return fmt.Errorf("input: %w", err) }
    if !inputInfo.Mode().IsRegular() { return errors.New("input must be a regular file") }
    raw, err := os.ReadFile(*input)
    if err != nil { return fmt.Errorf("input: %w", err) }
    if len(raw) > 1048576 || !utf8.Valid(raw) { return errors.New("input must be UTF-8 JSON, at most 1 MiB") }
    var records []string
    if err = json.Unmarshal(raw, &records); err != nil { return fmt.Errorf("records JSON: %w", err) }
    outputInfo, statErr := os.Stat(*output)
    if statErr == nil {
        if os.SameFile(inputInfo, outputInfo) { return errors.New("input and output must be different files") }
        if !outputInfo.Mode().IsRegular() && *output != "/dev/full" {
            return errors.New("output must be a regular file, or the explicit /dev/full fixture")
        }
    } else if !os.IsNotExist(statErr) { return fmt.Errorf("output: %w", statErr) }
    destination, err := os.Create(*output)
    if err != nil { return fmt.Errorf("create output: %w", err) }
    _ = practice.Export(destination, records)
    var wanted bytes.Buffer
    for _, record := range records { wanted.WriteString(record); wanted.WriteByte('\n') }
    digest := sha256.Sum256(wanted.Bytes())
    report := struct {
        Status string `json:"status"`
        Records int `json:"records"`
        Bytes int `json:"bytes"`
        SHA256 string `json:"sha256"`
    }{"complete", len(records), wanted.Len(), hex.EncodeToString(digest[:])}
    if err = json.NewEncoder(os.Stdout).Encode(report); err != nil {
        return fmt.Errorf("export completed; status output failed: %w", err)
    }
    return nil
}

func main() {
    if err := run(os.Args[1:]); err != nil {
        fmt.Fprintln(os.Stderr, err)
        os.Exit(2)
    }
}

